    if n < 2:
        return []
    if n == 4:
        return [[2, 2]]
    l = n - 2
    sieve = [True] * (l // 2)
    for i in range(3, int(l**0.5) + 1, 2):
        if sieve[i // 2]:
            sieve[i * i // 2::i] = [False] * ((l - i * i - 1) // (2 * i) + 1)
