def n_closestPairs_tonum(upper_lim, k):
    square_lim = int((2 * upper_lim) ** .5) + 1
    squares = [n*n for n in range(1, square_lim)]
    p, s = [], set(squares)
    for m in range(upper_lim - 1, 1, -1):
        for b in squares:
            if b >= m: break
            if 2*m - b in s:
                p.append([m, m - b])
                if len(p) == k: return p

class User(object):
    def __init__(self, name, balance, checking_account):
        self.name = name
        self.balance = balance
        self.checking_account = checking_account

    def withdraw(self, v):
        if v > self.balance: raise ValueError()
        self.balance -= v
        return "{} has {}.".format(self.name, int(self.balance))

    def add_cash(self, v):
        self.balance += v
        return "{} has {}.".format(self.name, int(self.balance))

    def check(self, other, v):
        if not other.checking_account: raise ValueError()
        s1,s2 = other.withdraw(v), self.add_cash(v)[:-1]
        return "{} and {}".format(s2,s1)

    def __str__(self): return "User({}, {}, {})".format(self.name, self.balance, self.checking_account)

def peak_height(mountain):
    M = {(r, c) for r, l in enumerate(mountain) for c in range(len(l)) if l[c] == '^'}
    h = 0
    while M:
        M -= {(r, c) for r, c in M if {(r, c+1), (r, c-1), (r+1, c), (r-1, c)} - M}
        h += 1
    return h

