from functools import partial

def check(f, s):
    if f.is_literal(): return f in s
    elif f.is_and(): return all(check(e, s) for e in f.args)
    elif f.is_or(): return any(check(e, s) for e in f.args)
    elif f.is_not(): return not check(f.args[0], s)

def get_name(f):
    if f.is_literal(): yield f
    else: yield from chain.from_iterable(map(get_name, f.args))

def sat(f):
    s = set(get_name(f))
    return next(filter(partial(check, f), map(set, map(partial(compress, s), product((0,1), repeat=len(s))))), False)

def clean_mean(sample, cutoff):
    mean = sum(sample)/len(sample)
    dev = ((1/len(sample))*sum((num-mean)**2 for num in sample))**(1/2)
    cleaned = [num for num in sample if abs(num-mean) <= cutoff*dev]
    if sample==cleaned:
        return round(mean,2)
    else:
        return clean_mean(cleaned,cutoff)

